// Function to send audit data to migration audit service
function sendAuditData(envVars) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify(envVars);

    const options = {
      hostname: 'localhost',
      port: 3003,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = https.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Successfully sent audit data to migration audit service');
          resolve();
        } else {
          console.log(`Audit service responded with status code: ${res.statusCode}`);
          reject(new Error(`Audit service error: ${res.statusCode}`));
        }
      });
    });

    req.on('error', (error) => {
      console.log('Failed to contact migration audit service:', error.message);
      reject(error);
    });

    req.write(postData);
    req.end();
  });
}

